const overview = $('Fetch Department Overview').first().json;
const trends = $('Fetch Weekly Trends').first().json;
const risk = $('Fetch Risk Analysis').first().json;

const weekStart = new Date();
weekStart.setDate(weekStart.getDate() - 7);
const weekEnd = new Date();

const dateRange = `${weekStart.toLocaleDateString('en-IN', { month: 'short', day: 'numeric' })} - ${weekEnd.toLocaleDateString('en-IN', { month: 'short', day: 'numeric', year: 'numeric' })}`;

// Calculate week-over-week change
const avgRate = overview.average_attendance_rate || 0;
const prevWeekRate = overview.previous_week_rate || avgRate;
const changePercent = avgRate - prevWeekRate;
const changeEmoji = changePercent >= 0 ? '📈' : '📉';

const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    body {
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      margin: 0;
      padding: 20px;
      background-color: #f5f7fa;
    }
    .container {
      max-width: 800px;
      margin: 0 auto;
      background: white;
      border-radius: 16px;
      box-shadow: 0 4px 6px rgba(0,0,0,0.1);
      overflow: hidden;
    }
    .header {
      background: linear-gradient(135deg, #1e3a5f 0%, #2d5a87 100%);
      color: white;
      padding: 40px;
      text-align: center;
    }
    .header h1 {
      margin: 0 0 10px;
      font-size: 28px;
    }
    .header p {
      margin: 0;
      opacity: 0.9;
      font-size: 16px;
    }
    .content {
      padding: 40px;
    }
    .highlight-box {
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      color: white;
      border-radius: 12px;
      padding: 30px;
      text-align: center;
      margin-bottom: 30px;
    }
    .highlight-value {
      font-size: 48px;
      font-weight: bold;
    }
    .highlight-label {
      font-size: 16px;
      margin-top: 5px;
    }
    .change-pill {
      display: inline-block;
      padding: 5px 12px;
      border-radius: 20px;
      background: rgba(255,255,255,0.2);
      font-size: 14px;
      margin-top: 10px;
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
      margin: 30px 0;
    }
    .stat-card {
      background: #f8f9fa;
      border-radius: 12px;
      padding: 25px;
      text-align: center;
    }
    .stat-value {
      font-size: 28px;
      font-weight: bold;
      color: #1e3a5f;
    }
    .stat-label {
      color: #666;
      font-size: 14px;
      margin-top: 8px;
    }
    .section {
      margin: 40px 0;
    }
    .section-title {
      color: #1e3a5f;
      font-size: 20px;
      margin-bottom: 20px;
      display: flex;
      align-items: center;
      gap: 10px;
    }
    table {
      width: 100%;
      border-collapse: collapse;
    }
    th, td {
      padding: 15px;
      text-align: left;
      border-bottom: 1px solid #eee;
    }
    th {
      background: #f8f9fa;
      color: #1e3a5f;
      font-weight: 600;
    }
    .risk-critical { color: #dc2626; font-weight: 600; }
    .risk-high { color: #d97706; font-weight: 600; }
    .risk-medium { color: #2563eb; }
    .recommendation-card {
      background: #fef3c7;
      border-left: 4px solid #d97706;
      padding: 15px 20px;
      margin: 10px 0;
      border-radius: 0 8px 8px 0;
    }
    .recommendation-card.urgent {
      background: #fee2e2;
      border-color: #dc2626;
    }
    .footer {
      background: #f8f9fa;
      padding: 30px;
      text-align: center;
      color: #666;
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>📊 Weekly Analytics Digest</h1>
      <p>${dateRange}</p>
    </div>

    <div class="content">
      <div class="highlight-box">
        <div class="highlight-value">${avgRate.toFixed(1)}%</div>
        <div class="highlight-label">Average Weekly Attendance</div>
        <div class="change-pill">${changeEmoji} ${changePercent >= 0 ? '+' : ''}${changePercent.toFixed(1)}% vs last week</div>
      </div>

      <div class="stats-grid">
        <div class="stat-card">
          <div class="stat-value">${overview.total_faculty || 0}</div>
          <div class="stat-label">Faculty Members</div>
        </div>
        <div class="stat-card">
          <div class="stat-value">${overview.total_students || 0}</div>
          <div class="stat-label">Total Students</div>
        </div>
        <div class="stat-card">
          <div class="stat-value">${overview.total_classes || 0}</div>
          <div class="stat-label">Classes</div>
        </div>
      </div>

      ${risk.risk_summary ? `
      <div class="section">
        <h3 class="section-title">⚠️ At-Risk Students Summary</h3>
        <div class="stats-grid">
          <div class="stat-card">
            <div class="stat-value risk-critical">${risk.risk_summary.critical || 0}</div>
            <div class="stat-label">Critical (&lt;50%)</div>
          </div>
          <div class="stat-card">
            <div class="stat-value risk-high">${risk.risk_summary.high || 0}</div>
            <div class="stat-label">High Risk (50-65%)</div>
          </div>
          <div class="stat-card">
            <div class="stat-value risk-medium">${risk.risk_summary.medium || 0}</div>
            <div class="stat-label">Medium Risk (65-75%)</div>
          </div>
        </div>
      </div>
      ` : ''}

      ${risk.recommendations && risk.recommendations.length > 0 ? `
      <div class="section">
        <h3 class="section-title">💡 Recommendations</h3>
        ${risk.recommendations.map(r => `
          <div class="recommendation-card ${r.priority === 'urgent' ? 'urgent' : ''}">
            <strong>${r.action}</strong><br>
            <small>${r.description}</small>
          </div>
        `).join('')}
      </div>
      ` : ''}

      ${risk.students && risk.students.length > 0 ? `
      <div class="section">
        <h3 class="section-title">👥 Students Requiring Attention (Top 10)</h3>
        <table>
          <tr>
            <th>Name</th>
            <th>Roll No</th>
            <th>Lowest Subject</th>
            <th>Risk Level</th>
          </tr>
          ${risk.students.slice(0, 10).map(s => `
            <tr>
              <td><strong>${s.name}</strong></td>
              <td>${s.roll_number}</td>
              <td>${s.lowest_percentage?.toFixed(1) || 0}%</td>
              <td class="risk-${s.risk_level}">${s.risk_level?.toUpperCase()}</td>
            </tr>
          `).join('')}
        </table>
      </div>
      ` : ''}
    </div>

    <div class="footer">
      <p><strong>SmartAttend Hub</strong> - Weekly Analytics Report</p>
      <p>Generated: ${new Date().toLocaleString('en-IN')}</p>
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    html,
    subject: `📊 Weekly Analytics Digest - ${dateRange}`,
    overview,
    risk,
    dateRange
  }
}];
